import{_ as t,c as a,o as i,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"n8n: workflow data and bounded automation","description":"","frontmatter":{},"headers":[],"relativePath":"applied-ai/n8n/index.md","filePath":"applied-ai/n8n/index.md"}'),s={name:"applied-ai/n8n/index.md"};function o(r,e,l,d,h,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="n8n-workflow-data-and-bounded-automation" tabindex="-1">n8n: workflow data and bounded automation <a class="header-anchor" href="#n8n-workflow-data-and-bounded-automation" aria-label="Permalink to “n8n: workflow data and bounded automation”">​</a></h1><p>n8n connects triggers, transformations and integrations in a visual workflow. It fits alongside application code: the workflow coordinates, while a custom service can own source authorization, typed business rules, index lifecycle, durable idempotency and approval receipts. A workflow that calls a model is not automatically an autonomous agent.</p><p><strong>Reference baseline:</strong> n8n 2.44.7, with official documentation checked on 2026-10-27. The <a href="https://github.com/n8n-io/n8n/releases/tag/n8n%402.44.7" target="_blank" rel="noreferrer">tagged release</a> exists; this is a study baseline, not a claim that it is the newest secure patch when you deploy. UI/node versions, editions and feature availability must be recorded for a real run. No n8n instance or workflow was published during this review.</p><h2 id="introductory-to-practical-order" tabindex="-1"><span class="hub-section-number">1 </span>Introductory-to-practical order <a class="header-anchor" href="#introductory-to-practical-order" aria-label="Permalink to “1 Introductory-to-practical order”">​</a></h2><ul><li>Understand the item envelope and expressions below using synthetic manual input.</li><li>Trace a condition and a subworkflow without credentials or side effects.</li><li>Follow <a href="./integration.html">webhook and custom-service integration</a>.</li><li>Apply <a href="./operations.html">errors, testing and deployment ownership</a>.</li><li>Perform the separate <a href="./../../practice/applied-ai/n8n-integration.html">N8N-P01 practice</a>, reusing the notes domain from P-334/P-335.</li></ul><h2 id="items-are-the-unit-of-data-flow" tabindex="-1"><span class="hub-section-number">2 </span>Items are the unit of data flow <a class="header-anchor" href="#items-are-the-unit-of-data-flow" aria-label="Permalink to “2 Items are the unit of data flow”">​</a></h2><p>A typical node receives and emits a list of items. Each item has a <code>json</code> object; binary data uses a separate <code>binary</code> field. A nested array inside one <code>json</code> object is <strong>not</strong> several items. Many nodes process each item, while some aggregate or run once for the whole collection; inspect the node&#39;s mode rather than assume a universal loop.</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;event_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;evt_1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;public&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refresh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;event_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;evt_2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;other&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refresh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Here there are two items. An HTTP node may therefore make two requests; limits/retries multiply that work. A batch body <code>{events:[...]}</code> would instead require explicit splitting. The <a href="https://docs.n8n.io/data/data-structure/" target="_blank" rel="noreferrer">official data-structure explanation</a> defines the envelope; it is not permission to trust the content.</p><h2 id="expressions-and-transformations" tabindex="-1"><span class="hub-section-number">3 </span>Expressions and transformations <a class="header-anchor" href="#expressions-and-transformations" aria-label="Permalink to “3 Expressions and transformations”">​</a></h2><p>An expression such as <code>{{ $json.source_id }}</code> reads the current item&#39;s field. Use the expression editor rather than treating user text as executable expression source. <code>$(&#39;Normalize&#39;).item.json.source_id</code> refers through item linking; <code>.first()</code> deliberately chooses one item and is not interchangeable with the matching item. Missing, split or aggregated links can make a previous-item reference ambiguous. Prefer explicit correlation IDs and current-item fields across integration boundaries. <a href="https://docs.n8n.io/code/expressions/" target="_blank" rel="noreferrer">Expressions</a>, <a href="https://docs.n8n.io/data/data-mapping/data-item-linking/item-linking-concepts/" target="_blank" rel="noreferrer">item linking</a>.</p><p>Use Edit Fields for simple projections, visual data nodes for common operations, and the Code node for a bounded transformation. Code has all-items and per-item modes. In all-items mode <code>$input.all()</code> supplies the collection; outputs that preserve one-to-one correspondence can carry <code>pairedItem: { item: index }</code>. Aggregation needs its own linking/correlation policy. Code-node availability of libraries/runtime features depends on hosting and runner configuration. Keep credentials and network calls out of the pure transform. <a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.code/" target="_blank" rel="noreferrer">Code node</a>.</p><h2 id="triggers-and-control-flow" tabindex="-1"><span class="hub-section-number">4 </span>Triggers and control flow <a class="header-anchor" href="#triggers-and-control-flow" aria-label="Permalink to “4 Triggers and control flow”">​</a></h2><table tabindex="0"><thead><tr><th>Mechanism</th><th>Role / boundary</th></tr></thead><tbody><tr><td>Manual Trigger</td><td>Synthetic development execution; not a public endpoint</td></tr><tr><td>Schedule Trigger</td><td>Time-based automation; record workflow/instance timezone and overlapping-run policy</td></tr><tr><td>Webhook</td><td>HTTP entry point with explicit method/auth/body/response contract</td></tr><tr><td>If / Switch</td><td>Choose branches from validated data, not permission from a source string</td></tr><tr><td>Merge</td><td>Combine streams under an explicit matching/append policy; matching by position can associate the wrong records</td></tr><tr><td>Execute Sub-workflow</td><td>Reuse a bounded contract with declared inputs/outputs and caller policy</td></tr></tbody></table><p>Branches do not imply parallel execution. Current workflow settings describe v1 branch ordering; do not rely on canvas geometry as a business transaction policy. A subworkflow must validate scope/inputs and define whether the parent waits for completion. Fire-and-forget changes receipt/error ownership; it is not a way to hide a failed critical step. Use an ID-based join when ordering may change. <a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.if/" target="_blank" rel="noreferrer">If</a>, <a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.merge/" target="_blank" rel="noreferrer">Merge</a>, <a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.executeworkflow/" target="_blank" rel="noreferrer">subworkflows</a>, <a href="https://docs.n8n.io/workflows/settings/" target="_blank" rel="noreferrer">settings</a>.</p><p><a href="./../../workbench/applied-ai/n8n/">Runnable transform/reference adapter</a> · <a href="./integration.html">Next: integration</a></p>`,16)])])}const k=t(s,[["render",o]]);export{u as __pageData,k as default};
